package app.p3r.dayplanner.v2;
import android.app.Activity;import android.content.Context;import android.graphics.*;import android.view.*;import android.widget.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import java.io.*;import static org.junit.Assert.*;import app.p3r.dayplanner.R;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28,qualifiers="en-rUS-w320dp-h640dp-xhdpi",shadows={GoalPlannerWidgetTest.RealAnimator.class})
public class GoalPlannerWidgetTest {
 private Context c;private final File output=new File("/workspace/shared/planner_v2/qa/native_goal_widget");
 @Before public void setup(){c=RuntimeEnvironment.getApplication();output.mkdirs();}
 private JSONObject plan()throws Exception{return new JSONObject().put("steps",new JSONArray().put(new JSONObject().put("action_id","p3r.social.magician").put("slot",GameDate.slot(10,22,false))).put(new JSONObject().put("action_id","__wait__").put("slot",GameDate.slot(10,22,true))).put(new JSONObject().put("action_id","p3r.stat.study").put("slot",GameDate.slot(10,22,true)))).put("action_metadata",new JSONObject().put("p3r.social.magician",new JSONObject().put("display_title","魔术师 · 2 → 3").put("entity","magician")).put("p3r.stat.study",new JSONObject().put("display_title","房间学习 · 按实际属性重新规划"))).put("adaptive_reservations",new JSONArray().put(new JSONObject().put("slot",GameDate.slot(10,23,true)).put("display_title","爬塔预留 · 现金与楼层按实际结果记录").put("kind","dungeon")));}
 private JSONObject snapshot()throws Exception{return new JSONObject().put("game_slot",GameDate.slot(10,22,false)).put("revision",2);}
 private View render(int width,int height,int index)throws Exception{View v=GoalPlannerWidget.render(c,snapshot(),plan(),index,width,height).apply(c,new FrameLayout(c));v.measure(View.MeasureSpec.makeMeasureSpec(width*2,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(height*2,View.MeasureSpec.EXACTLY));v.layout(0,0,width*2,height*2);return v;}
 @Test public void itemsExcludeWaitSortAndRetainConditionalIdentity()throws Exception{JSONArray a=GoalPlannerWidget.items(plan());assertEquals(3,a.length());assertEquals("social",a.getJSONObject(0).getString("kind"));assertEquals("stats",a.getJSONObject(1).getString("kind"));assertEquals("tower",a.getJSONObject(2).getString("kind"));assertTrue(a.getJSONObject(2).getBoolean("reservation"));assertEquals("magician",a.getJSONObject(0).getString("entity"));}
 @Test @Config(sdk={26,28,35}) public void remoteViewsInflateAndInitialHostDoesNotAnimate()throws Exception{for(int index=0;index<3;index++){RemoteViews content=GoalPlannerWidget.render(c,snapshot(),plan(),index,180,160);View host=GoalPlannerWidget.hostViews(c,content,index>0,false).apply(c,new FrameLayout(c));assertEquals(View.VISIBLE,host.findViewById(R.id.widget_palette_static).getVisibility());ViewFlipper f=host.findViewById(R.id.widget_palette_flipper);assertFalse(f.isFlipping());assertFalse(f.getAnimateFirstView());assertEquals(220,f.getInAnimation().getDuration());}}
 @Test public void emptyPlanHasNoCompletableForecast()throws Exception{View v=GoalPlannerWidget.render(c,null,new JSONObject(),0,180,160).apply(c,new FrameLayout(c));assertFalse(v.findViewById(R.id.button_spec_done).isEnabled());assertEquals("选择目标，从当前存档开始",((TextView)v.findViewById(R.id.widget_task)).getText().toString());}
 @Test @GraphicsMode(GraphicsMode.Mode.NATIVE) public void nativeSmallMediumWideCardsAreReadable()throws Exception{for(int width:new int[]{180,250,320})for(int index=0;index<3;index++){int height=width==180?160:200;View v=render(width,height,index);TextView title=v.findViewById(R.id.widget_task),cue=v.findViewById(R.id.widget_detail_cue);assertEquals(80,v.findViewById(R.id.button_spec_done).getHeight());assertEquals(80,v.findViewById(R.id.button_spec_current).getHeight());assertTrue("title fits",title.getLayout().getHeight()<=title.getHeight());assertTrue("cue fits vertically",cue.getLayout().getHeight()<=cue.getHeight());TextView day=v.findViewById(R.id.widget_day_number);assertTrue("full day number fits width "+width,day.getPaint().measureText(day.getText().toString())<=day.getWidth()-day.getCompoundPaddingLeft()-day.getCompoundPaddingRight()+1);assertEquals(View.GONE,v.findViewById(R.id.widget_dialogue_choices).getVisibility());Bitmap b=Bitmap.createBitmap(width*2,height*2,Bitmap.Config.ARGB_8888);v.draw(new Canvas(b));try(FileOutputStream stream=new FileOutputStream(new File(output,"card-"+width+"-"+index+".png"))){b.compress(Bitmap.CompressFormat.PNG,100,stream);}}}
 @Implements(android.widget.ViewAnimator.class) public static class RealAnimator extends org.robolectric.shadows.ShadowViewGroup {}
 @Test @Config(shadows={RealAnimator.class}) @GraphicsMode(GraphicsMode.Mode.NATIVE) public void attachedReapplyDrawsOldBlendedAndNewFrames()throws Exception{Activity activity=Robolectric.buildActivity(Activity.class).setup().get();FrameLayout container=new FrameLayout(activity);activity.setContentView(container);RemoteViews day=GoalPlannerWidget.render(activity,snapshot(),plan(),0,250,200);View root=GoalPlannerWidget.hostViews(activity,day,false,false).apply(activity,container);container.addView(root);size(root);ViewFlipper first=root.findViewById(R.id.widget_palette_flipper);RemoteViews night=GoalPlannerWidget.render(activity,snapshot(),plan(),1,250,200);GoalPlannerWidget.hostViews(activity,night,true,true).reapply(activity,root);size(root);ViewFlipper f=root.findViewById(R.id.widget_palette_flipper);assertSame(first,f);assertEquals(View.GONE,root.findViewById(R.id.widget_palette_static).getVisibility());for(int i=0;i<2;i++){assertNotNull(f.getChildAt(i).getAnimation());f.getChildAt(i).getAnimation().setStartTime(1000);}int[] pixels=new int[3];for(int i=0;i<3;i++){Object attach=org.robolectric.util.ReflectionHelpers.getField(root,"mAttachInfo");org.robolectric.util.ReflectionHelpers.setField(attach,"mDrawingTime",new long[]{1000,1110,1230}[i]);Bitmap b=Bitmap.createBitmap(500,400,Bitmap.Config.ARGB_8888);root.draw(new Canvas(b));pixels[i]=b.getPixel(250,160);try(FileOutputStream stream=new FileOutputStream(new File(output,"fade-"+i+".png"))){b.compress(Bitmap.CompressFormat.PNG,100,stream);}}assertNotEquals(pixels[0],pixels[1]);assertNotEquals(pixels[1],pixels[2]);GoalPlannerWidget.hostViews(activity,night,true,false).reapply(activity,root);assertSame(first,root.findViewById(R.id.widget_palette_flipper));assertEquals(View.VISIBLE,root.findViewById(R.id.widget_palette_static).getVisibility());activity.finish();}
 private void size(View v){v.measure(View.MeasureSpec.makeMeasureSpec(500,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(400,View.MeasureSpec.EXACTLY));v.layout(0,0,500,400);}
}
